import {primaryJourneyProgress} from './expedition-journey-followthrough.mjs';
import {GEAR,EXPEDITIONS} from './expedition-data.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reward=r=>`通过${r.cleared}场 · ${r.gold}金币 · 每位出战者${r.xp}经验${r.loot?.length?' · '+r.loot.map(id=>GEAR[id]?.name||id).join('、'):''}`;
function journeyHints(c){const items=(c.journeys||[]).filter(j=>!(c.primary.action==='journey'&&c.primary.value===j.id));if(!items.length)return '';const ready=items.filter(j=>j.canClaim).length;return `<details class=camp-journeys ${ready?'open':''}><summary>旅程手记 · ${items.length}段有进展${ready?' · '+ready+'段可交付':''}</summary>${items.map(j=>`<article data-camp-journey="${j.id}"><p>${esc(j.label)} · ${j.completed}/${j.total||3} · ${j.canClaim?'可选择一次结局':j.ready?'条件已齐，先领取当前远征':'尚有未完成的条件'}</p><button data-cycle-action=journey data-cycle-value="${j.id}">${j.canClaim?'查看并选择结局':'查看旅程下一步'} →</button></article>`).join('')}<small>这里只展示已领取成果的进展；查看不会代领或替你选择结局。</small></details>`;}
function secondaryRetry(c){
 const last=c.last,stopped=last?.won===false,goalMissed=last?.won===true&&last.objective?.met===false;
 if(!c.heroId||c.stage==='pending'||c.stage==='hero'||c.primary.action==='retry'||!Number.isSafeInteger(last?.id)||last.id<1||!stopped&&!goalMissed)return '';
 return `<div class="camp-secondary-retry"><p>第${last.id}次${stopped?'远征已止步':'已通关，但所选攻略目标未达成'}，实际收益已领取。可载入当时方案再检查；当前任务进度保留。</p><button data-cycle-action="retry" data-cycle-value="${last.id}">载入第${last.id}次${stopped?'止步方案':'目标与方案'} →</button><small>载入只进入远征准备；不立即出征，也不再次领奖。</small></div>`;
}

export function campCycleView(c){const journey=primaryJourneyProgress(c);return `<section class="panel camp-cycle" data-cycle-stage="${c.stage}"><p class=eyebrow>营地目标 / 正式出征 → 复盘 → 领取 → 成长 → 再出发</p><h2><img src="assets/camp-waypost-v190.svg" width="28" height="28" alt="" aria-hidden="true" style="vertical-align:middle;margin-right:.35em">${esc(c.title)}</h2><p>${esc(c.text)}</p>${journey?`<p class="camp-primary-journey" role="status">${esc(journey.label)} · ${journey.completed}/${journey.total} · ${esc(journey.status)}</p>`:''}${c.last?`<p class=cycle-receipt>最近远征已领取：第${c.last.id}次 · ${esc(EXPEDITIONS[c.last.route].name)} · ${reward(c.last)}</p>`:''}<div class=bar><button class=primary data-cycle-action="${c.primary.action}" data-cycle-value="${c.primary.value}">${esc(c.primary.label)} →</button>${c.heroId&&c.primary.action!=='training'?'<button data-cycle-action=training>我的成长</button>':''}${c.heroId?'<button data-cycle-action=equipment>我的装备</button>':''}${c.stage==='growth'?'<button data-cycle-action=prepare data-cycle-value=chapter>先继续第一章</button>':''}${c.stage==='explore'?'<button data-cycle-action=goals>选择攻略目标</button>':''}${c.primary.action!=='map'?'<button data-cycle-action=map>自由选择路线</button>':''}</div>${secondaryRetry(c)}${journeyHints(c)}${c.introSkipped?'<p class="muted">你已领取其他路线的通关成果，无须补做起步路线；回声侧廊和修道院短线仍可在地图自由选择。</p>':''}<small>已通关${c.cleared}/${c.total}条路线。目标是可跳过的探索指引，不是难度排名、培养门槛或额外任务奖励。</small></section>`;}
export function reportHandoffView(s,objective=''){return `<p class=eyebrow>战报来源 / 归营交接</p><h2>${esc(s.title)}</h2><p>${esc(s.text)}</p>${objective}${s.receipt?`<p class=handoff-reward>${reward(s.receipt)}</p>`:''}<div class=bar>${s.status==='pending'?'<button class=primary data-report-cycle=claim>领取本次收益并归营</button>':s.status==='claimed'?'<button class=primary data-report-cycle=training>去查看我的成长</button>':s.status==='recorded'?'<button class=primary data-report-cycle=goals>回看攻略目标</button>':'<button class=primary data-report-cycle=official>回营核对正式出征</button>'}${s.otherPending?`<button data-report-cycle=pending>另有第${s.otherPending}次待结算 · 查看该次战报</button>`:''}<button data-report-cycle=camp>返回营地</button></div>`;}
